64	            {batchSize, maxDepth}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "acceptedTokenIds");
65	        rt::Tensor acceptedLogitsIndicesTensor(
66	            {batchSize, maxDepth}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "acceptedLogitsIndices");
67	        rt::Tensor acceptLengthTensor({batchSize}, rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "acceptLength");
