84	            vocabMappingTableTensor = rt::Tensor({static_cast<int64_t>(vocabMappingTableData.size())},
85	                rt::DeviceType::kGPU, nvinfer1::DataType::kINT32, "vocabMappingTable");
86	            copyHostToDevice(vocabMappingTableTensor, vocabMappingTableData);
