88	        }
89	
90	        // Execute kernel with timing
91	        auto start = std::chrono::high_resolution_clock::now();
92	        EXPECT_NO_THROW({
93	            kernel::eagleAccept(logitsTensor, tokenIdsTensor, attentionMaskTensor, acceptedTokenIdsTensor,
94	                acceptedLogitsIndicesTensor, acceptLengthTensor, vocabMappingTable, workspace, workspaceSize, stream);
95	            CUDA_CHECK(cudaDeviceSynchronize());
96	        });
97	        auto end = std::chrono::high_resolution_clock::now();
98	        auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(end - start);
99	
100	        // Cleanup workspace
101	        CUDA_CHECK(cudaFree(workspace));
102	
103	        // Run reference implementation for comparison
104	        EagleAcceptResult refResult = eagleAcceptRef(
105	            logits, tokenIds, attentionMask, batchSize, numTokens, vocabSize, maxDepth, vocabMappingTableData);
106	
107	        // Copy results back to host for validation
108	        std::vector<int32_t> hostAcceptedTokenIds(batchSize * maxDepth);
109	        std::vector<int32_t> hostAcceptedLogitsIndices(batchSize * maxDepth);
110	        std::vector<int32_t> hostAcceptLengths(batchSize);
111	
112	        hostAcceptedTokenIds = copyDeviceToHost<int32_t>(acceptedTokenIdsTensor);
113	        hostAcceptedLogitsIndices = copyDeviceToHost<int32_t>(acceptedLogitsIndicesTensor);
114	        hostAcceptLengths = copyDeviceToHost<int32_t>(acceptLengthTensor);
115	
116	        // Basic performance check
117	        EXPECT_LT(duration.count(), 1000) << testName << ": Kernel took too long, possible infinite loop";
118	
119	        // Validate results against reference implementation
120	        for (int32_t b = 0; b < batchSize; ++b)
121	        {
122	            EXPECT_EQ(hostAcceptLengths[b], refResult.acceptLengths[b])
123	                << testName << ": Accept length mismatch at batch " << b;
124	
125	            // Check accepted tokens and indices
126	            for (int32_t i = 0; i < hostAcceptLengths[b]; ++i)
127	            {
128	                int32_t idx = b * maxDepth + i;
129	                EXPECT_EQ(hostAcceptedTokenIds[idx], refResult.acceptedTokenIds[b * refResult.maxAcceptLength + i])
130	                    << testName << ": Token ID mismatch at batch " << b << " position " << i;
131	                EXPECT_EQ(
132	                    hostAcceptedLogitsIndices[idx], refResult.acceptedLogitsIndices[b * refResult.maxAcceptLength + i])
133	                    << testName << ": Logits index mismatch at batch " << b << " position " << i;
134	            }
135	
136	            // Check that unused positions are properly initialized to 0
137	            // (Changed from -1 to 0 to avoid embedding lookup issues in draft model)
138	            for (int32_t i = hostAcceptLengths[b]; i < maxDepth; ++i)
139	            {
140	                int32_t idx = b * maxDepth + i;
141	                EXPECT_EQ(hostAcceptedTokenIds[idx], 0)
142	                    << testName << ": Unused token ID position should be 0 at batch " << b << " position " << i;
143	                EXPECT_EQ(hostAcceptedLogitsIndices[idx], -1)
144	                    << testName << ": Unused logits index position should be -1 at batch " << b << " position " << i;
145	            }
146	        }
147	
148	        // Run custom validation if provided
149	        if (validator)
150	        {
151	            validator(hostAcceptedTokenIds, hostAcceptedLogitsIndices, hostAcceptLengths, refResult);
152	        }
153	        std::cout << testName << " - Duration: " << duration.count() << "ms" << std::endl;
154	        std::cout << "Accept lengths: ";
155	        for (int32_t b = 0; b < batchSize; ++b)
156	        {
157	            std::cout << hostAcceptLengths[b] << " ";
158	        }
159	        std::cout << std::endl;
160	        for (int32_t b = 0; b < batchSize; ++b)
