192	    tokenIds[0 * numTokens + 1] = 2;
193	    tokenIds[0 * numTokens + 2] = 3;
194	    tokenIds[1 * numTokens + 0] = 4;
195	    tokenIds[1 * numTokens + 1] = 5;
196	    tokenIds[1 * numTokens + 2] = 6;
197	
198	    std::vector<int8_t> attentionMask(batchSize * numTokens * numTokens, 0);
199	
200	    // Batch 0: full chain attention pattern (1->2->3)
201	    attentionMask[0 * numTokens * numTokens + 0 * numTokens + 0] = 1;
202	    attentionMask[0 * numTokens * numTokens + 1 * numTokens + 0] = 1;
203	    attentionMask[0 * numTokens * numTokens + 1 * numTokens + 1] = 1;
204	    attentionMask[0 * numTokens * numTokens + 2 * numTokens + 0] = 1;
205	    attentionMask[0 * numTokens * numTokens + 2 * numTokens + 1] = 1;
206	    attentionMask[0 * numTokens * numTokens + 2 * numTokens + 2] = 1;
207	
208	    // Batch 1: partial chain (4->5, no continuation to 6)
209	    attentionMask[1 * numTokens * numTokens + 0 * numTokens + 0] = 1;
210	    attentionMask[1 * numTokens * numTokens + 1 * numTokens + 0] = 1;
211	    attentionMask[1 * numTokens * numTokens + 1 * numTokens + 1] = 1;
212	
213	    // Setup logits to favor the expected path with more realistic values
214	    std::vector<float> logits(batchSize * numTokens * vocabSize, -5.0f);
215	
216	    // Add some noise to avoid uniform values
217	    for (int32_t i = 0; i < batchSize * numTokens * vocabSize; ++i)
218	    {
219	        logits[i] += (i % 7) * 0.01f; // Small variation to break ties consistently
220	    }
221	
222	    logits[0 * numTokens * vocabSize + 0 * vocabSize + 2] = 5.0f; // pos 0 -> token 2
223	    logits[0 * numTokens * vocabSize + 1 * vocabSize + 3] = 5.0f; // pos 1 -> token 3
224	    logits[0 * numTokens * vocabSize + 2 * vocabSize + 0] = 5.0f; // pos 2 -> token 0 (default)
225	    logits[1 * numTokens * vocabSize + 0 * vocabSize + 5] = 5.0f; // pos 0 -> token 5
226	    logits[1 * numTokens * vocabSize + 1 * vocabSize + 0] = 5.0f; // pos 1 -> token 0 (default)
227	
228	    runEagleAcceptTest(tokenIds, attentionMask, logits, batchSize, numTokens, vocabSize, maxDepth, "PerBatchDesignTest",
229	        [](auto const& acceptedTokenIds, auto const& acceptedLogitsIndices, auto const& acceptLengths, auto const&) {
230	            EXPECT_EQ(acceptLengths[0], 3) << "Batch 0 should accept 3 tokens (2->3->something)";
231	            EXPECT_EQ(acceptLengths[1], 2) << "Batch 1 should accept 2 tokens (5->something)";
232	
233	            EXPECT_EQ(acceptedTokenIds[0 * 3 + 0], 2) << "Batch 0 token 0";
234	            EXPECT_EQ(acceptedTokenIds[0 * 3 + 1], 3) << "Batch 0 token 1";
235	            EXPECT_EQ(acceptedLogitsIndices[0 * 3 + 0], 0) << "Batch 0 logits index 0";
236	            EXPECT_EQ(acceptedLogitsIndices[0 * 3 + 1], 1) << "Batch 0 logits index 1";
237	            EXPECT_EQ(acceptedLogitsIndices[0 * 3 + 2], 2) << "Batch 0 logits index 2";
238	
239	            EXPECT_EQ(acceptedTokenIds[1 * 3 + 0], 5) << "Batch 1 token 0";
240	            EXPECT_EQ(acceptedLogitsIndices[1 * 3 + 0], 0) << "Batch 1 logits index 0";
241	            EXPECT_EQ(acceptedLogitsIndices[1 * 3 + 1], 1) << "Batch 1 logits index 1";
242	
243	            EXPECT_EQ(acceptedTokenIds[1 * 3 + 2], 0) << "Batch 1 unused token position should be 0";
244	            EXPECT_EQ(acceptedLogitsIndices[1 * 3 + 2], -1) << "Batch 1 unused logits index position should be -1";
245	        });
