248	// Test complex multi-batch scenario with varying tree structures and early termination
249	TEST_F(EagleAcceptTest, MultiBatchAsymmetricTree)
250	{
251	    constexpr int32_t numTokens = 5;
252	    constexpr int32_t batchSize = 6;
253	    constexpr int32_t vocabSize = 150;
254	    constexpr int32_t maxDepth = 5;
255	
256	    /*
257	     * BATCH 0: Tree [90->91->92->93->94], logits 91,92,93,94,0 -> [91,92,93,94,0] length=5
258	     * BATCH 1: Tree [90->95->96], logits 95,96,149(not in tree) -> [95,96,149] length=3
259	     * BATCH 2: Tree [90->97->98->99->89], logits 97,98,99,89,0 -> [97,98,99,89,0] length=5
260	     * BATCH 3: Tree [90->88], logits 88,149(not in tree) -> [88,149] length=2
261	     * BATCH 4: Tree [90->87->86->85->84], logits 87,86,85,84,0 -> [87,86,85,84,0] length=5
262	     * BATCH 5: Tree [90], logits 149(not in tree) -> [149] length=1
263	     */
264	
265	    std::vector<int32_t> tokenIds(batchSize * numTokens);
266	    std::vector<int8_t> attentionMask(batchSize * numTokens * numTokens, 0);
267	
268	    // Batch 0: long chain [90->91->92->93->94]
269	    tokenIds[0 * numTokens + 0] = 90;
270	    tokenIds[0 * numTokens + 1] = 91;
271	    tokenIds[0 * numTokens + 2] = 92;
272	    tokenIds[0 * numTokens + 3] = 93;
273	    tokenIds[0 * numTokens + 4] = 94;
274	
275	    // Batch 1: short chain [90->95->96] with early termination
276	    tokenIds[1 * numTokens + 0] = 90;
277	    tokenIds[1 * numTokens + 1] = 95;
278	    tokenIds[1 * numTokens + 2] = 96;
279	    tokenIds[1 * numTokens + 3] = 97;
280	    tokenIds[1 * numTokens + 4] = 98;
281	
282	    // Batch 2: different long chain [90->97->98->99->89]
283	    tokenIds[2 * numTokens + 0] = 90;
284	    tokenIds[2 * numTokens + 1] = 97;
285	    tokenIds[2 * numTokens + 2] = 98;
286	    tokenIds[2 * numTokens + 3] = 99;
287	    tokenIds[2 * numTokens + 4] = 89;
288	
289	    // Batch 3: minimal chain [90->88] with early termination
290	    tokenIds[3 * numTokens + 0] = 90;
291	    tokenIds[3 * numTokens + 1] = 88;
292	    tokenIds[3 * numTokens + 2] = 87;
293	    tokenIds[3 * numTokens + 3] = 86;
294	    tokenIds[3 * numTokens + 4] = 85;
295	
296	    // Batch 4: full chain [90->87->86->85->84]
