298	    tokenIds[4 * numTokens + 1] = 87;
299	    tokenIds[4 * numTokens + 2] = 86;
300	    tokenIds[4 * numTokens + 3] = 85;
301	    tokenIds[4 * numTokens + 4] = 84;
302	
303	    // Batch 5: no continuation [90] (logits favor non-existent tokens)
304	    tokenIds[5 * numTokens + 0] = 90;
305	    tokenIds[5 * numTokens + 1] = 83;
306	    tokenIds[5 * numTokens + 2] = 82;
307	    tokenIds[5 * numTokens + 3] = 81;
308	    tokenIds[5 * numTokens + 4] = 80;
309	
310	    // Define valid token count per batch for attention mask setup
311	    int32_t validTokensPerBatch[] = {5, 3, 5, 2, 5, 5};
312	
313	    // Create triangular attention masks for each batch based on valid token count
314	    for (int32_t b = 0; b < batchSize; ++b)
315	    {
316	        for (int32_t i = 0; i < validTokensPerBatch[b]; ++i)
317	        {
318	            for (int32_t j = 0; j <= i; ++j)
319	            {
320	                attentionMask[b * numTokens * numTokens + i * numTokens + j] = 1;
321	            }
322	        }
