328	    // Add some noise to avoid uniform values and ensure consistent tie-breaking
329	    for (int32_t i = 0; i < batchSize * numTokens * vocabSize; ++i)
330	    {
331	        logits[i] += (i % 13) * 0.01f; // Small variation to break ties consistently
332	    }
333	
334	    // Batch 0: favor path [90->91->92->93->94]
335	    logits[0 * numTokens * vocabSize + 0 * vocabSize + 91] = 10.0f;
336	    logits[0 * numTokens * vocabSize + 1 * vocabSize + 92] = 10.0f;
337	    logits[0 * numTokens * vocabSize + 2 * vocabSize + 93] = 10.0f;
338	    logits[0 * numTokens * vocabSize + 3 * vocabSize + 94] = 10.0f;
339	    logits[0 * numTokens * vocabSize + 4 * vocabSize + 0] = 10.0f; // final position -> token 0
340	
341	    // Batch 1: favor path [90->95->96], then non-existent token for early termination
342	    logits[1 * numTokens * vocabSize + 0 * vocabSize + 95] = 10.0f;
343	    logits[1 * numTokens * vocabSize + 1 * vocabSize + 96] = 10.0f;
344	    logits[1 * numTokens * vocabSize + 2 * vocabSize + 149] = 10.0f; // non-existent token
345	    logits[1 * numTokens * vocabSize + 3 * vocabSize + 0] = 10.0f;   // default token
346	    logits[1 * numTokens * vocabSize + 4 * vocabSize + 0] = 10.0f;   // default token
347	
348	    // Batch 2: favor path [90->97->98->99->89]
349	    logits[2 * numTokens * vocabSize + 0 * vocabSize + 97] = 10.0f;
350	    logits[2 * numTokens * vocabSize + 1 * vocabSize + 98] = 10.0f;
351	    logits[2 * numTokens * vocabSize + 2 * vocabSize + 99] = 10.0f;
352	    logits[2 * numTokens * vocabSize + 3 * vocabSize + 89] = 10.0f;
353	    logits[2 * numTokens * vocabSize + 4 * vocabSize + 0] = 10.0f; // final position -> token 0
354	
355	    // Batch 3: favor path [90->88], then non-existent token for early termination
356	    logits[3 * numTokens * vocabSize + 0 * vocabSize + 88] = 10.0f;
357	    logits[3 * numTokens * vocabSize + 1 * vocabSize + 149] = 10.0f; // non-existent token
358	    logits[3 * numTokens * vocabSize + 2 * vocabSize + 0] = 10.0f;   // default token
359	    logits[3 * numTokens * vocabSize + 3 * vocabSize + 0] = 10.0f;   // default token
360	    logits[3 * numTokens * vocabSize + 4 * vocabSize + 0] = 10.0f;   // default token
361	
362	    // Batch 4: favor path [90->87->86->85->84]
363	    logits[4 * numTokens * vocabSize + 0 * vocabSize + 87] = 10.0f;
364	    logits[4 * numTokens * vocabSize + 1 * vocabSize + 86] = 10.0f;
365	    logits[4 * numTokens * vocabSize + 2 * vocabSize + 85] = 10.0f;
366	    logits[4 * numTokens * vocabSize + 3 * vocabSize + 84] = 10.0f;
367	    logits[4 * numTokens * vocabSize + 4 * vocabSize + 0] = 10.0f; // final position -> token 0
368	
369	    // Batch 5: favor non-existent token immediately for no continuation
370	    logits[5 * numTokens * vocabSize + 0 * vocabSize + 149] = 15.0f; // non-existent token
371	    logits[5 * numTokens * vocabSize + 0 * vocabSize + 83] = 5.0f;   // valid but lower priority
372	    logits[5 * numTokens * vocabSize + 1 * vocabSize + 0] = 10.0f;   // default token
373	    logits[5 * numTokens * vocabSize + 2 * vocabSize + 0] = 10.0f;   // default token
374	    logits[5 * numTokens * vocabSize + 3 * vocabSize + 0] = 10.0f;   // default token
375	    logits[5 * numTokens * vocabSize + 4 * vocabSize + 0] = 10.0f;   // default token
376	
377	    runEagleAcceptTest(tokenIds, attentionMask, logits, batchSize, numTokens, vocabSize, maxDepth,
378	        "AsymmetricTreeMultiBatch",
