389	            EXPECT_EQ(acceptedTokenIds[0 * 5 + 1], 92) << "Batch 0 path A token 1";
390	            EXPECT_EQ(acceptedTokenIds[0 * 5 + 2], 93) << "Batch 0 path A token 2";
