533	    // Add some noise to avoid uniform values and ensure consistent tie-breaking
534	    for (int32_t i = 0; i < batchSize * numTokens * vocabSize; ++i)
535	    {
536	        logits[i] += (i % 17) * 0.01f; // Small variation to break ties consistently
537	    }
538	
539	    // Batch 0: favor path [100->200->300->400]
540	    logits[0 * numTokens * vocabSize + 0 * vocabSize + 200] = 10.0f;
541	    logits[0 * numTokens * vocabSize + 1 * vocabSize + 300] = 10.0f;
542	    logits[0 * numTokens * vocabSize + 2 * vocabSize + 400] = 10.0f;
