552	    logits[2 * numTokens * vocabSize + 0 * vocabSize + 201] = 10.0f;
553	    logits[2 * numTokens * vocabSize + 1 * vocabSize + 304] = 10.0f;
554	    logits[2 * numTokens * vocabSize + 2 * vocabSize + 999] = 10.0f; // non-existent token
