591	// Test single batch with logit-controlled early termination
592	TEST_F(EagleAcceptTest, SingleBatchLogitTermination)
593	{
594	    constexpr int32_t numTokens = 5;
595	    constexpr int32_t batchSize = 1;
596	    constexpr int32_t vocabSize = 50;
597	    constexpr int32_t maxDepth = 5;
598	
599	    /*
600	     * Tree [15->25->35->45->49], logits pos0->25, pos1->35, pos2->48(not in tree, higher than 45)
601	     * Expected: [25,35,48] indices=[0,1,2] length=3 (stops when 48 not found in tree)
602	     */
603	
604	    // Setup a complete tree but use logits to cause early termination
605	    std::vector<int32_t> tokenIds(batchSize * numTokens);
606	    tokenIds[0] = 15; // root
607	    tokenIds[1] = 25; // depth 2
608	    tokenIds[2] = 35; // depth 3
609	    tokenIds[3] = 45; // depth 4
610	    tokenIds[4] = 49; // depth 5
611	
612	    // Create full triangular attention mask (all tokens can attend to previous ones)
613	    std::vector<int8_t> attentionMask(batchSize * numTokens * numTokens, 0);
614	
615	    for (int32_t i = 0; i < numTokens; ++i)
616	    {
617	        for (int32_t j = 0; j <= i; ++j)
618	        {
619	            attentionMask[i * numTokens + j] = 1;
620	        }
621	    }
622	
623	    // Setup logits to cause termination at position 2
624	    std::vector<float> logits(batchSize * numTokens * vocabSize, -5.0f);
625	
626	    // Add some noise to avoid uniform values and ensure consistent tie-breaking
627	    for (int32_t i = 0; i < batchSize * numTokens * vocabSize; ++i)
628	    {
629	        logits[i] += (i % 19) * 0.01f; // Small variation to break ties consistently
630	    }
631	
632	    logits[0 * vocabSize + 25] = 10.0f; // pos 0 -> token 25 (valid)
633	    logits[1 * vocabSize + 35] = 10.0f; // pos 1 -> token 35 (valid)
634	    logits[2 * vocabSize + 48] = 15.0f; // pos 2 -> token 48 (not in tree, higher priority)
635	    logits[2 * vocabSize + 45] = 5.0f;  // pos 2 -> token 45 (valid but lower priority)
636	    logits[3 * vocabSize + 0] = 10.0f;  // pos 3 -> token 0 (default)
637	    logits[4 * vocabSize + 0] = 10.0f;  // pos 4 -> token 0 (default)
638	
639	    runEagleAcceptTest(tokenIds, attentionMask, logits, batchSize, numTokens, vocabSize, maxDepth,
640	        "SingleBatchLogitTermination",
641	        [](auto const& acceptedTokenIds, auto const& acceptedLogitsIndices, auto const& acceptLengths, auto const&) {
642	            EXPECT_EQ(acceptLengths[0], 3) << "Should accept 3 tokens: 25->35->48";
643	            EXPECT_EQ(acceptedTokenIds[0], 25) << "First predicted token";
644	            EXPECT_EQ(acceptedTokenIds[1], 35) << "Second predicted token";
645	            EXPECT_EQ(acceptedTokenIds[2], 48) << "Third predicted token (not in tree)";
646	            EXPECT_EQ(acceptedLogitsIndices[0], 0) << "First logits index";
647	            EXPECT_EQ(acceptedLogitsIndices[1], 1) << "Second logits index";
648	            EXPECT_EQ(acceptedLogitsIndices[2], 2) << "Third logits index";
649	
650	            EXPECT_EQ(acceptedTokenIds[3], 0) << "Unused token position should be 0";
651	            EXPECT_EQ(acceptedLogitsIndices[3], -1) << "Unused logits index position should be -1";
652	            EXPECT_EQ(acceptedTokenIds[4], 0) << "Unused token position should be 0";
653	            EXPECT_EQ(acceptedLogitsIndices[4], -1) << "Unused logits index position should be -1";
654	        });
655	}
