741	// Test vocabulary reduction with mapping table - single batch
742	TEST_F(EagleAcceptTest, VocabularyReductionSingleBatch)
743	{
744	    constexpr int32_t numTokens = 4;
745	    constexpr int32_t batchSize = 1;
746	    constexpr int32_t reducedVocabSize = 8; // Reduced vocabulary (output by model)
747	    constexpr int32_t maxDepth = 4;
748	
749	    /*
750	     * Reduced vocab [0,1,2,3,4,5,6,7] maps to full vocab [50,51,52,53,54,55,56,57]
751	     * Tree [50->51->52->53] in full vocab space
752	     * Logits predict [1,2,3,0] in reduced vocab -> maps to [51,52,53,50] in full vocab
753	     * Expected: [51,52,53,50] indices=[0,1,2,3] length=4
754	     */
755	
756	    // Setup vocab mapping table: reduced vocab index -> full vocab token
757	    std::vector<int32_t> vocabMappingTable(reducedVocabSize);
758	    for (int32_t i = 0; i < reducedVocabSize; ++i)
759	    {
760	        vocabMappingTable[i] = 50 + i; // Maps 0->50, 1->51, ..., 7->57
761	    }
762	
763	    // Setup token IDs in full vocab space: [50, 51, 52, 53]
764	    std::vector<int32_t> tokenIds(batchSize * numTokens);
765	    tokenIds[0] = 50;
766	    tokenIds[1] = 51;
767	    tokenIds[2] = 52;
768	    tokenIds[3] = 53;
769	
770	    // Setup triangular attention mask (full chain)
771	    std::vector<int8_t> attentionMask(batchSize * numTokens * numTokens, 0);
772	    for (int32_t i = 0; i < numTokens; ++i)
773	    {
774	        for (int32_t j = 0; j <= i; ++j)
775	        {
776	            attentionMask[i * numTokens + j] = 1;
777	        }
778	    }
779	
780	    // Setup logits in REDUCED vocab space
781	    std::vector<float> logits(batchSize * numTokens * reducedVocabSize, -5.0f);
782	
783	    // Add noise
784	    for (int32_t i = 0; i < batchSize * numTokens * reducedVocabSize; ++i)
785	    {
786	        logits[i] += (i % 7) * 0.01f;
787	    }
788	
789	    // Favor path in reduced vocab: [1,2,3,0] -> maps to full vocab [51,52,53,50]
790	    logits[0 * reducedVocabSize + 1] = 10.0f; // pos 0 -> reduced 1 -> full 51
791	    logits[1 * reducedVocabSize + 2] = 10.0f; // pos 1 -> reduced 2 -> full 52
792	    logits[2 * reducedVocabSize + 3] = 10.0f; // pos 2 -> reduced 3 -> full 53
793	    logits[3 * reducedVocabSize + 0] = 10.0f; // pos 3 -> reduced 0 -> full 50
794	
795	    runEagleAcceptTest(
